626	    yield text(`answer ${run}`);
627	    await gates[run].until;
628	    yield STOP;
629	  };
630	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
631	  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);
632	
633	  return {
634	    session,
635	    handed,
636	    release: (run: number) => gates[run].release(),
637	    close: () => {
638	      socket.readyState = WebSocket.CLOSED;
639	    },
640	    frames: () => wire(sent),
641	    send: (raw: unknown) => handle(ws, session, raw),
642	  };
